import {crops} from './life-state.js';
export function createGardenUI({context,action,close,toast}){
 const el=document.createElement('dialog');el.id='garden-picker';el.setAttribute('aria-label','花园');document.body.append(el);
 const ids=Object.keys(crops);let plot=0,cursor=0,world=null,working=false,serial=0,timer,choosing=false;
 const c=context,plant=()=>c().state.worlds[world]?.life?.plots?.[plot];
 function hide(){serial++;clearTimeout(timer);el.close();c().visual?.gardenSelect(-1)}
 function choose(index){cursor=Math.max(0,Math.min(ids.length-1,index));const wheel=el.querySelector('.garden-wheel');if(!wheel)return;wheel.setAttribute('aria-activedescendant','seed-'+ids[cursor]);wheel.querySelectorAll('[role=option]').forEach((o,i)=>o.setAttribute('aria-selected',i===cursor));}
 function render(){if(world!==c().world)return hide();const p=plant(),ready=p&&p.readyAt<=Date.now();if(p&&p.watered&&!ready){hide();return}el.classList.toggle('choosing',!p&&choosing);el.innerHTML=p?'<footer>'+(!p.watered?'<button data-water>浇水</button>':'')+(ready?'<button data-harvest>采摘</button>':'')+'</footer>':choosing?'<div class="sleep-wheel-shell"><div class="sleep-wheel-band"></div><div class="sleep-wheel garden-wheel" tabindex="0" role="listbox" aria-label="花和蔬果">'+ids.map((id,i)=>'<div role="option" id="seed-'+id+'" aria-selected="'+(i===cursor)+'"><i style="background:#'+crops[id].color.toString(16).padStart(6,'0')+'"></i>'+crops[id].name+'</div>').join('')+'</div></div><footer><button data-plant>种花</button></footer>':'<footer><button data-choose>种花</button></footer>';if(!el.open)el.show();c().visual?.gardenSelect(plot);
 const chooseButton=el.querySelector('[data-choose]');if(chooseButton)chooseButton.onclick=()=>{choosing=true;render()};
 const wheel=el.querySelector('.garden-wheel');if(wheel){wheel.scrollTop=cursor*48;choose(cursor);wheel.onscroll=()=>{clearTimeout(timer);timer=setTimeout(()=>choose(Math.round(wheel.scrollTop/48)),100)};wheel.onclick=e=>{const option=e.target.closest('[role=option]');if(!option)return;choose(ids.indexOf(option.id.slice(5)));wheel.scrollTo({top:cursor*48,behavior:'smooth'})};wheel.onkeydown=e=>{if(!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();choose(e.key==='Home'?0:e.key==='End'?ids.length-1:cursor+(e.key==='ArrowDown'?1:-1));wheel.scrollTop=cursor*48};el.querySelector('[data-plant]').onclick=()=>{choose(Math.round(wheel.scrollTop/48));perform('plant',ids[cursor])}}else if(p){const water=el.querySelector('[data-water]'),harvest=el.querySelector('[data-harvest]');if(water)water.onclick=()=>perform('water',p.crop);if(harvest)harvest.onclick=()=>perform('harvest',p.crop)}}
 function growth(){if(!el.open||working)return;const p=plant();if(p&&p.readyAt<=Date.now()&&!el.querySelector('[data-harvest]'))render()}
 async function perform(type,crop){if(working)return;working=true;choosing=false;const token=++serial,target=world,index=plot;el.close();try{const animated=await c().visual?.gardenAnimate(type,index,crop);if(animated===false||serial!==token||c().world!==target)return;await action({type,plot:index,crop});}finally{working=false;if(serial===token&&c().world===target)render()}}
 function open(index){if(working)return;choosing=false;close();world=c().world;plot=Number.isInteger(index)?index:Math.max(0,(c().state.worlds[world].life?.plots||[]).findIndex(p=>!p));c().visual?.inspectGarden();render()}
 document.addEventListener('pointerdown',e=>{if(el.open&&!el.contains(e.target))hide()},true);
 el.addEventListener('cancel',hide);setInterval(growth,1000);return {open,hide};
}
